dslRule:
/*!id: replace-deprecated-keysequence-array*/
/*!description: Replace deprecated org.eclipse.ui.keys.KeySequence[] with org.eclipse.jface.bindings.TriggerSequence[].*/
/*!severity: WARNING*/

org.eclipse.ui.keys.KeySequence[]
=>
org.eclipse.jface.bindings.TriggerSequence[]
;;

beforeExample:
package org.eclipse.test;

import org.eclipse.ui.commands.ICommand;
import org.eclipse.ui.keys.KeySequence; // Deprecated type

public class ExampleClass {
    // Field declaration
    private KeySequence[] fieldSequences;

    // Method return type
    public KeySequence[] getSequences() {
        return fieldSequences;
    }

    public void processSequences() {
        // Local variable declaration
        KeySequence[] localSequences = getSequences();
        System.out.println(localSequences.length);
    }
}

afterExample:
package org.eclipse.test;

import org.eclipse.ui.commands.ICommand;
import org.eclipse.jface.bindings.TriggerSequence; // Replacement type

public class ExampleClass {
    // Field declaration
    private TriggerSequence[] fieldSequences;

    // Method return type
    public TriggerSequence[] getSequences() {
        return fieldSequences;
    }

    public void processSequences() {
        // Local variable declaration
        TriggerSequence[] localSequences = getSequences();
        System.out.println(localSequences.length);
    }
}

negativeExample:
package org.eclipse.test;

import org.eclipse.ui.keys.KeySequence; // Deprecated non-array type

public class NegativeExample {
    private KeySequence singleSequence; // Should not match, it's not an array
    public KeySequence getSingleSequence() { // Should not match
        return singleSequence;
    }
    public void test() {
        KeySequence localSingleSequence = getSingleSequence(); // Should not match
        System.out.println(localSingleSequence);
    }
}
